<?php
session_start();require_once __DIR__.'/config/db.php';if(empty($_SESSION['user_id'])){header('Location: ../login.php');exit;}$id=$_SESSION['user_id'];$nome=htmlspecialchars($_SESSION['nome']);$ruolo=$_SESSION['ruolo'];$classe=$_SESSION['classe']??'';$today=(int)date('N');
if($ruolo==='studente'){$q=$pdo->prepare("SELECT COUNT(*) t,SUM(stato='presente') p FROM presenze WHERE studente_id=?");$q->execute([$id]);$r=$q->fetch();$tot=(int)$r['t'];$presenti=(int)$r['p'];$perc=$tot?round($presenti/$tot*100):0;$q=$pdo->prepare('SELECT AVG(voto) m FROM voti WHERE studente_id=?');$q->execute([$id]);$media=$q->fetch()['m'];$q=$pdo->prepare('SELECT COUNT(*) c FROM messaggi WHERE destinatario_id=? AND letto=0');$q->execute([$id]);$unread=(int)$q->fetch()['c'];$q=$pdo->prepare('SELECT v.descrizione,v.data,m.nome materia FROM verifiche v JOIN materie m ON m.id=v.materia_id WHERE v.classe=? AND v.data>=CURDATE() ORDER BY v.data LIMIT 1');$q->execute([$classe]);$next=$q->fetch();$q=$pdo->prepare('SELECT o.ora_inizio,o.ora_fine,m.nome materia FROM orario o JOIN materie m ON m.id=o.materia_id WHERE o.classe=? AND o.giorno_settimana=? ORDER BY o.ora_inizio');$q->execute([$classe,$today]);$schedule=$q->fetchAll();$q=$pdo->prepare('SELECT p.data,p.stato,p.note,m.nome materia FROM presenze p LEFT JOIN materie m ON m.id=p.materia_id WHERE p.studente_id=? ORDER BY p.data DESC LIMIT 5');$q->execute([$id]);$attendance=$q->fetchAll();}
$pageTitle='Panoramica';$active='dashboard';require __DIR__.'/config/auth.php';require __DIR__.'/includes/header.php';require __DIR__.'/includes/sidebar.php';?><main class="main"><header class="topbar"><h1>Panoramica</h1><div class="user-menu"><?=$nome?> · <?=e(ucfirst($ruolo))?> · <a href="logout.php">Esci</a></div></header><section class="content"><div class="page-head"><h2>Benvenuto, <?=$nome?></h2><p>Riepilogo delle informazioni più importanti.</p></div><?php if($ruolo==='studente'): ?><div class="grid"><article class="card"><div class="stat-label">Presenze</div><div class="stat-number"><?=$perc?>%</div><div class="muted"><?=$presenti?> su <?=$tot?></div></article><article class="card"><div class="stat-label">Media voti</div><div class="stat-number"><?=$media!==null?number_format($media,1):'N/D'?></div><div class="muted">Valutazioni registrate</div></article><article class="card"><div class="stat-label">Messaggi non letti</div><div class="stat-number"><?=$unread?></div><div class="muted">Comunicazioni da leggere</div></article><article class="card"><div class="stat-label">Prossima verifica</div><div class="stat-number"><?=$next?e($next['materia']):'-'?></div><div class="muted"><?=$next?e($next['descrizione']).' · '.date('d/m/Y',strtotime($next['data'])):'Nessuna verifica'?></div></article></div><div class="section"><h3>Orario di oggi</h3><div class="table-wrap"><table><thead><tr><th>Ora</th><th>Materia</th></tr></thead><tbody><?php foreach($schedule as $o): ?><tr><td><?=substr($o['ora_inizio'],0,5)?> - <?=substr($o['ora_fine'],0,5)?></td><td><?=e($o['materia'])?></td></tr><?php endforeach ?></tbody></table></div></div><div class="section"><h3>Ultime presenze</h3><div class="table-wrap"><table><thead><tr><th>Data</th><th>Materia</th><th>Stato</th><th>Note</th></tr></thead><tbody><?php foreach($attendance as $a): ?><tr><td><?=date('d/m/Y',strtotime($a['data']))?></td><td><?=e($a['materia']??'-')?></td><td class="<?= $a['stato']==='presente'?'good':'warn'?>"><?=e(ucfirst($a['stato']))?></td><td><?=e($a['note']??'-')?></td></tr><?php endforeach ?></tbody></table></div></div><?php else: ?><div class="card">Dashboard professore pronta per il modulo registro.</div><?php endif ?></section></main><?php require __DIR__.'/includes/footer.php'; ?>